/* wl_shm.error, since 3: wl_shm error values */
enum jwl_wl_shm_error {
    JWL_WL_SHM_ERROR_INVALID_FORMAT = 0, /* buffer format is not known */
    JWL_WL_SHM_ERROR_INVALID_STRIDE = 1, /* invalid size or stride during pool creation */
    JWL_WL_SHM_ERROR_INVALID_FD = 2,     /* mmapping the file descriptor failed */
};

