    status_t (*set_transient)(void *data, uint32_t self, uint32_t parent, int32_t x, int32_t y,
                              uint32_t flags);
    status_t (*set_fullscreen)(void *data, uint32_t self, uint32_t method, uint32_t framerate,
                               uint32_t output);
    status_t (*set_popup)(void *data, uint32_t self, uint32_t seat, uint32_t serial,
                          uint32_t parent, int32_t x, int32_t y, uint32_t flags);
    status_t (*set_maximized)(void *data, uint32_t self, uint32_t output);
    status_t (*set_title)(void *data, uint32_t self, const char *title);
