/* Calls h's handler for wl_shell_surface request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_shell_surface
 * doesn't have. */
static inline status_t jwl_wl_shell_surface_dispatch_request(
        const struct jwl_wl_shell_surface_requests *h, void *data, uint32_t self, uint32_t opcode,
        const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_SHELL_SURFACE_REQ_PONG:
        if (!h->pong)
            return ERR_NOT_SUPPORTED;
        return h->pong(data, self, a[0].u);
    case JWL_WL_SHELL_SURFACE_REQ_MOVE:
        if (!h->move)
            return ERR_NOT_SUPPORTED;
        return h->move(data, self, a[0].o, a[1].u);
    case JWL_WL_SHELL_SURFACE_REQ_RESIZE:
        if (!h->resize)
            return ERR_NOT_SUPPORTED;
        return h->resize(data, self, a[0].o, a[1].u, a[2].u);
    case JWL_WL_SHELL_SURFACE_REQ_SET_TOPLEVEL:
        if (!h->set_toplevel)
            return ERR_NOT_SUPPORTED;
        return h->set_toplevel(data, self);
    case JWL_WL_SHELL_SURFACE_REQ_SET_TRANSIENT:
        if (!h->set_transient)
            return ERR_NOT_SUPPORTED;
        return h->set_transient(data, self, a[0].o, a[1].i, a[2].i, a[3].u);
    case JWL_WL_SHELL_SURFACE_REQ_SET_FULLSCREEN:
        if (!h->set_fullscreen)
            return ERR_NOT_SUPPORTED;
        return h->set_fullscreen(data, self, a[0].u, a[1].u, a[2].o);
    case JWL_WL_SHELL_SURFACE_REQ_SET_POPUP:
        if (!h->set_popup)
            return ERR_NOT_SUPPORTED;
        return h->set_popup(data, self, a[0].o, a[1].u, a[2].o, a[3].i, a[4].i, a[5].u);
    case JWL_WL_SHELL_SURFACE_REQ_SET_MAXIMIZED:
        if (!h->set_maximized)
            return ERR_NOT_SUPPORTED;
        return h->set_maximized(data, self, a[0].o);
    case JWL_WL_SHELL_SURFACE_REQ_SET_TITLE:
        if (!h->set_title)
            return ERR_NOT_SUPPORTED;
        return h->set_title(data, self, a[0].s);
    case JWL_WL_SHELL_SURFACE_REQ_SET_CLASS:
        if (!h->set_class)
            return ERR_NOT_SUPPORTED;
        return h->set_class(data, self, a[0].s);
    }
    return ERR_INVALID_ARGS;
}

/* Calls h's handler for wl_shell_surface event `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_shell_surface
 * doesn't have. */
static inline status_t jwl_wl_shell_surface_dispatch_event(
        const struct jwl_wl_shell_surface_events *h, void *data, uint32_t self, uint32_t opcode,
        const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_SHELL_SURFACE_EV_PING:
        if (!h->ping)
            return ERR_NOT_SUPPORTED;
        return h->ping(data, self, a[0].u);
    case JWL_WL_SHELL_SURFACE_EV_CONFIGURE:
        if (!h->configure)
            return ERR_NOT_SUPPORTED;
        return h->configure(data, self, a[0].u, a[1].i, a[2].i);
    case JWL_WL_SHELL_SURFACE_EV_POPUP_DONE:
        if (!h->popup_done)
            return ERR_NOT_SUPPORTED;
        return h->popup_done(data, self);
    }
    return ERR_INVALID_ARGS;
}


/* ---- wl_surface, upstream version 7: an onscreen surface ---- */

#define JWL_WL_SURFACE_VERSION 7u

/* wl_surface requests: the opcode, and the version each came in. */
#define JWL_WL_SURFACE_REQ_DESTROY                    0u
#define JWL_WL_SURFACE_REQ_DESTROY_SINCE              1u
#define JWL_WL_SURFACE_REQ_ATTACH                     1u
#define JWL_WL_SURFACE_REQ_ATTACH_SINCE               1u
#define JWL_WL_SURFACE_REQ_DAMAGE                     2u
#define JWL_WL_SURFACE_REQ_DAMAGE_SINCE               1u
#define JWL_WL_SURFACE_REQ_FRAME                      3u
#define JWL_WL_SURFACE_REQ_FRAME_SINCE                1u
#define JWL_WL_SURFACE_REQ_SET_OPAQUE_REGION          4u
#define JWL_WL_SURFACE_REQ_SET_OPAQUE_REGION_SINCE    1u
#define JWL_WL_SURFACE_REQ_SET_INPUT_REGION           5u
#define JWL_WL_SURFACE_REQ_SET_INPUT_REGION_SINCE     1u
#define JWL_WL_SURFACE_REQ_COMMIT                     6u
#define JWL_WL_SURFACE_REQ_COMMIT_SINCE               1u
#define JWL_WL_SURFACE_REQ_SET_BUFFER_TRANSFORM       7u
#define JWL_WL_SURFACE_REQ_SET_BUFFER_TRANSFORM_SINCE 2u
#define JWL_WL_SURFACE_REQ_SET_BUFFER_SCALE           8u
#define JWL_WL_SURFACE_REQ_SET_BUFFER_SCALE_SINCE     3u
#define JWL_WL_SURFACE_REQ_DAMAGE_BUFFER              9u
#define JWL_WL_SURFACE_REQ_DAMAGE_BUFFER_SINCE        4u
#define JWL_WL_SURFACE_REQ_OFFSET                     10u
#define JWL_WL_SURFACE_REQ_OFFSET_SINCE               5u
#define JWL_WL_SURFACE_REQ_GET_RELEASE                11u
#define JWL_WL_SURFACE_REQ_GET_RELEASE_SINCE          7u
#define JWL_WL_SURFACE_REQ_DESTRUCTORS                0x00000001u

/* wl_surface events: the opcode, and the version each came in. */
#define JWL_WL_SURFACE_EV_ENTER                            0u
#define JWL_WL_SURFACE_EV_ENTER_SINCE                      1u
#define JWL_WL_SURFACE_EV_LEAVE                            1u
#define JWL_WL_SURFACE_EV_LEAVE_SINCE                      1u
#define JWL_WL_SURFACE_EV_PREFERRED_BUFFER_SCALE           2u
#define JWL_WL_SURFACE_EV_PREFERRED_BUFFER_SCALE_SINCE     6u
#define JWL_WL_SURFACE_EV_PREFERRED_BUFFER_TRANSFORM       3u
#define JWL_WL_SURFACE_EV_PREFERRED_BUFFER_TRANSFORM_SINCE 6u
#define JWL_WL_SURFACE_EV_DESTRUCTORS                      0x00000000u

/* wl_surface.error: wl_surface error values */
enum jwl_wl_surface_error {
    JWL_WL_SURFACE_ERROR_INVALID_SCALE = 0,       /* buffer scale value is invalid */
    JWL_WL_SURFACE_ERROR_INVALID_TRANSFORM = 1,   /* buffer transform value is invalid */
    JWL_WL_SURFACE_ERROR_INVALID_SIZE = 2,        /* buffer size is invalid */
    JWL_WL_SURFACE_ERROR_INVALID_OFFSET = 3,      /* buffer offset is invalid */
    JWL_WL_SURFACE_ERROR_DEFUNCT_ROLE_OBJECT = 4, /* surface was destroyed before its role object */
    JWL_WL_SURFACE_ERROR_NO_BUFFER = 5,           /* no buffer was attached */
};

/* What the compositor does with each wl_surface request: one handler per
 * message, or NULL (its dispatcher answers ERR_NOT_SUPPORTED). Each gets
 * the object's data (what libjwl's object map holds for it), its id
 * and the arguments the codec decoded and checked. */
struct jwl_wl_surface_requests {
    status_t (*destroy)(void *data, uint32_t self);
    status_t (*attach)(void *data, uint32_t self, uint32_t buffer, int32_t x, int32_t y);
    status_t (*damage)(void *data, uint32_t self, int32_t x, int32_t y, int32_t width,
                       int32_t height);
    status_t (*frame)(void *data, uint32_t self, uint32_t callback);
    status_t (*set_opaque_region)(void *data, uint32_t self, uint32_t region);
    status_t (*set_input_region)(void *data, uint32_t self, uint32_t region);
    status_t (*commit)(void *data, uint32_t self);
    status_t (*set_buffer_transform)(void *data, uint32_t self, int32_t transform);
    status_t (*set_buffer_scale)(void *data, uint32_t self, int32_t scale);
    status_t (*damage_buffer)(void *data, uint32_t self, int32_t x, int32_t y, int32_t width,
                              int32_t height);
    status_t (*offset)(void *data, uint32_t self, int32_t x, int32_t y);
    status_t (*get_release)(void *data, uint32_t self, uint32_t callback);
};

/* What a client does with each wl_surface event: one handler per
 * message, or NULL (its dispatcher answers ERR_NOT_SUPPORTED). Each gets
 * the object's data (what libjwl's object map holds for it), its id
 * and the arguments the codec decoded and checked. */
struct jwl_wl_surface_events {
    status_t (*enter)(void *data, uint32_t self, uint32_t output);
    status_t (*leave)(void *data, uint32_t self, uint32_t output);
    status_t (*preferred_buffer_scale)(void *data, uint32_t self, int32_t factor);
    status_t (*preferred_buffer_transform)(void *data, uint32_t self, uint32_t transform);
};

