/* Calls h's handler for wl_surface request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_surface
 * doesn't have. */
static inline status_t jwl_wl_surface_dispatch_request(const struct jwl_wl_surface_requests *h,
                                                       void *data, uint32_t self, uint32_t opcode,
                                                       const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_SURFACE_REQ_DESTROY:
        if (!h->destroy)
            return ERR_NOT_SUPPORTED;
        return h->destroy(data, self);
    case JWL_WL_SURFACE_REQ_ATTACH:
        if (!h->attach)
            return ERR_NOT_SUPPORTED;
        return h->attach(data, self, a[0].o, a[1].i, a[2].i);
    case JWL_WL_SURFACE_REQ_DAMAGE:
        if (!h->damage)
            return ERR_NOT_SUPPORTED;
        return h->damage(data, self, a[0].i, a[1].i, a[2].i, a[3].i);
    case JWL_WL_SURFACE_REQ_FRAME:
        if (!h->frame)
            return ERR_NOT_SUPPORTED;
        return h->frame(data, self, a[0].n);
    case JWL_WL_SURFACE_REQ_SET_OPAQUE_REGION:
        if (!h->set_opaque_region)
            return ERR_NOT_SUPPORTED;
        return h->set_opaque_region(data, self, a[0].o);
    case JWL_WL_SURFACE_REQ_SET_INPUT_REGION:
        if (!h->set_input_region)
            return ERR_NOT_SUPPORTED;
        return h->set_input_region(data, self, a[0].o);
    case JWL_WL_SURFACE_REQ_COMMIT:
        if (!h->commit)
            return ERR_NOT_SUPPORTED;
        return h->commit(data, self);
    case JWL_WL_SURFACE_REQ_SET_BUFFER_TRANSFORM:
        if (!h->set_buffer_transform)
            return ERR_NOT_SUPPORTED;
        return h->set_buffer_transform(data, self, a[0].i);
    case JWL_WL_SURFACE_REQ_SET_BUFFER_SCALE:
        if (!h->set_buffer_scale)
            return ERR_NOT_SUPPORTED;
        return h->set_buffer_scale(data, self, a[0].i);
    case JWL_WL_SURFACE_REQ_DAMAGE_BUFFER:
        if (!h->damage_buffer)
            return ERR_NOT_SUPPORTED;
        return h->damage_buffer(data, self, a[0].i, a[1].i, a[2].i, a[3].i);
    case JWL_WL_SURFACE_REQ_OFFSET:
        if (!h->offset)
            return ERR_NOT_SUPPORTED;
        return h->offset(data, self, a[0].i, a[1].i);
    case JWL_WL_SURFACE_REQ_GET_RELEASE:
        if (!h->get_release)
            return ERR_NOT_SUPPORTED;
        return h->get_release(data, self, a[0].n);
    }
    return ERR_INVALID_ARGS;
}

/* Calls h's handler for wl_surface event `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_surface
 * doesn't have. */
static inline status_t jwl_wl_surface_dispatch_event(const struct jwl_wl_surface_events *h,
                                                     void *data, uint32_t self, uint32_t opcode,
                                                     const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_SURFACE_EV_ENTER:
        if (!h->enter)
            return ERR_NOT_SUPPORTED;
        return h->enter(data, self, a[0].o);
    case JWL_WL_SURFACE_EV_LEAVE:
        if (!h->leave)
            return ERR_NOT_SUPPORTED;
        return h->leave(data, self, a[0].o);
    case JWL_WL_SURFACE_EV_PREFERRED_BUFFER_SCALE:
        if (!h->preferred_buffer_scale)
            return ERR_NOT_SUPPORTED;
        return h->preferred_buffer_scale(data, self, a[0].i);
    case JWL_WL_SURFACE_EV_PREFERRED_BUFFER_TRANSFORM:
        if (!h->preferred_buffer_transform)
            return ERR_NOT_SUPPORTED;
        return h->preferred_buffer_transform(data, self, a[0].u);
    }
    return ERR_INVALID_ARGS;
}


