/* Calls h's handler for wl_pointer request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_pointer
 * doesn't have. */
static inline status_t jwl_wl_pointer_dispatch_request(const struct jwl_wl_pointer_requests *h,
                                                       void *data, uint32_t self, uint32_t opcode,
                                                       const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_POINTER_REQ_SET_CURSOR:
        if (!h->set_cursor)
            return ERR_NOT_SUPPORTED;
        return h->set_cursor(data, self, a[0].u, a[1].o, a[2].i, a[3].i);
    case JWL_WL_POINTER_REQ_RELEASE:
        if (!h->release)
            return ERR_NOT_SUPPORTED;
        return h->release(data, self);
    }
    return ERR_INVALID_ARGS;
}

/* Calls h's handler for wl_pointer event `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_pointer
 * doesn't have. */
static inline status_t jwl_wl_pointer_dispatch_event(const struct jwl_wl_pointer_events *h,
                                                     void *data, uint32_t self, uint32_t opcode,
                                                     const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_POINTER_EV_ENTER:
        if (!h->enter)
            return ERR_NOT_SUPPORTED;
        return h->enter(data, self, a[0].u, a[1].o, a[2].f, a[3].f);
    case JWL_WL_POINTER_EV_LEAVE:
        if (!h->leave)
            return ERR_NOT_SUPPORTED;
        return h->leave(data, self, a[0].u, a[1].o);
    case JWL_WL_POINTER_EV_MOTION:
        if (!h->motion)
            return ERR_NOT_SUPPORTED;
        return h->motion(data, self, a[0].u, a[1].f, a[2].f);
    case JWL_WL_POINTER_EV_BUTTON:
        if (!h->button)
            return ERR_NOT_SUPPORTED;
        return h->button(data, self, a[0].u, a[1].u, a[2].u, a[3].u);
    case JWL_WL_POINTER_EV_AXIS:
        if (!h->axis)
            return ERR_NOT_SUPPORTED;
        return h->axis(data, self, a[0].u, a[1].u, a[2].f);
    case JWL_WL_POINTER_EV_FRAME:
        if (!h->frame)
            return ERR_NOT_SUPPORTED;
        return h->frame(data, self);
    case JWL_WL_POINTER_EV_AXIS_SOURCE:
        if (!h->axis_source)
            return ERR_NOT_SUPPORTED;
        return h->axis_source(data, self, a[0].u);
    case JWL_WL_POINTER_EV_AXIS_STOP:
        if (!h->axis_stop)
            return ERR_NOT_SUPPORTED;
        return h->axis_stop(data, self, a[0].u, a[1].u);
    case JWL_WL_POINTER_EV_AXIS_DISCRETE:
        if (!h->axis_discrete)
            return ERR_NOT_SUPPORTED;
        return h->axis_discrete(data, self, a[0].u, a[1].i);
    case JWL_WL_POINTER_EV_AXIS_VALUE120:
        if (!h->axis_value120)
            return ERR_NOT_SUPPORTED;
        return h->axis_value120(data, self, a[0].u, a[1].i);
    case JWL_WL_POINTER_EV_AXIS_RELATIVE_DIRECTION:
        if (!h->axis_relative_direction)
            return ERR_NOT_SUPPORTED;
        return h->axis_relative_direction(data, self, a[0].u, a[1].u);
    case JWL_WL_POINTER_EV_WARP:
        if (!h->warp)
            return ERR_NOT_SUPPORTED;
        return h->warp(data, self, a[0].f, a[1].f);
    }
    return ERR_INVALID_ARGS;
}


/* ---- wl_keyboard, upstream version 11: keyboard input device ---- */

#define JWL_WL_KEYBOARD_VERSION 11u

/* wl_keyboard requests: the opcode, and the version each came in. */
#define JWL_WL_KEYBOARD_REQ_RELEASE       0u
#define JWL_WL_KEYBOARD_REQ_RELEASE_SINCE 3u
#define JWL_WL_KEYBOARD_REQ_DESTRUCTORS   0x00000001u

/* wl_keyboard events: the opcode, and the version each came in. */
#define JWL_WL_KEYBOARD_EV_KEYMAP            0u
#define JWL_WL_KEYBOARD_EV_KEYMAP_SINCE      1u
#define JWL_WL_KEYBOARD_EV_ENTER             1u
#define JWL_WL_KEYBOARD_EV_ENTER_SINCE       1u
#define JWL_WL_KEYBOARD_EV_LEAVE             2u
#define JWL_WL_KEYBOARD_EV_LEAVE_SINCE       1u
#define JWL_WL_KEYBOARD_EV_KEY               3u
#define JWL_WL_KEYBOARD_EV_KEY_SINCE         1u
#define JWL_WL_KEYBOARD_EV_MODIFIERS         4u
#define JWL_WL_KEYBOARD_EV_MODIFIERS_SINCE   1u
#define JWL_WL_KEYBOARD_EV_REPEAT_INFO       5u
#define JWL_WL_KEYBOARD_EV_REPEAT_INFO_SINCE 4u
#define JWL_WL_KEYBOARD_EV_DESTRUCTORS       0x00000000u

/* wl_keyboard.keymap_format: keyboard mapping format */
enum jwl_wl_keyboard_keymap_format {
    /* no keymap; client must understand how to interpret the raw keycode */
    JWL_WL_KEYBOARD_KEYMAP_FORMAT_NO_KEYMAP = 0,
    /* libxkbcommon compatible, null-terminated string; to determine the xkb keycode, clients
     * must add 8 to the key event keycode */
    JWL_WL_KEYBOARD_KEYMAP_FORMAT_XKB_V1 = 1,
};

/* wl_keyboard.key_state: physical key state */
enum jwl_wl_keyboard_key_state {
    JWL_WL_KEYBOARD_KEY_STATE_RELEASED = 0, /* key is not pressed */
    JWL_WL_KEYBOARD_KEY_STATE_PRESSED = 1,  /* key is pressed */
    JWL_WL_KEYBOARD_KEY_STATE_REPEATED = 2, /* key was repeated */
};
#define JWL_WL_KEYBOARD_KEY_STATE_REPEATED_SINCE 10u

/* What the compositor does with each wl_keyboard request: one handler per
 * message, or NULL (its dispatcher answers ERR_NOT_SUPPORTED). Each gets
 * the object's data (what libjwl's object map holds for it), its id
 * and the arguments the codec decoded and checked. */
struct jwl_wl_keyboard_requests {
    status_t (*release)(void *data, uint32_t self);
};

/* What a client does with each wl_keyboard event: one handler per
 * message, or NULL (its dispatcher answers ERR_NOT_SUPPORTED). Each gets
 * the object's data (what libjwl's object map holds for it), its id
 * and the arguments the codec decoded and checked. */
struct jwl_wl_keyboard_events {
    status_t (*keymap)(void *data, uint32_t self, uint32_t format, handle_t fd, uint32_t size);
    status_t (*enter)(void *data, uint32_t self, uint32_t serial, uint32_t surface,
                      const void *keys, uint32_t keys_size);
    status_t (*leave)(void *data, uint32_t self, uint32_t serial, uint32_t surface);
    status_t (*key)(void *data, uint32_t self, uint32_t serial, uint32_t time, uint32_t key,
                    uint32_t state);
    status_t (*modifiers)(void *data, uint32_t self, uint32_t serial, uint32_t mods_depressed,
                          uint32_t mods_latched, uint32_t mods_locked, uint32_t group);
    status_t (*repeat_info)(void *data, uint32_t self, int32_t rate, int32_t delay);
};

/* wl_keyboard.release, request 0, since 3, destroys the object: release the keyboard object */
static inline status_t jwl_wl_keyboard_release(struct jwl_conn *c, uint32_t self)
{
    return jwl_send(c, self, JWL_WL_KEYBOARD_REQ_RELEASE,
                    &jwl_wl_keyboard_interface.requests[JWL_WL_KEYBOARD_REQ_RELEASE], NULL);
}

/* wl_keyboard.keymap, event 0: keyboard mapping */
