/* Calls h's handler for wl_keyboard request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_keyboard
 * doesn't have. */
static inline status_t jwl_wl_keyboard_dispatch_request(const struct jwl_wl_keyboard_requests *h,
                                                        void *data, uint32_t self, uint32_t opcode,
                                                        const union jwl_arg *a)
{
    (void)a;
    switch (opcode) {
    case JWL_WL_KEYBOARD_REQ_RELEASE:
        if (!h->release)
            return ERR_NOT_SUPPORTED;
        return h->release(data, self);
    }
    return ERR_INVALID_ARGS;
}

/* Calls h's handler for wl_keyboard event `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_keyboard
 * doesn't have. */
static inline status_t jwl_wl_keyboard_dispatch_event(const struct jwl_wl_keyboard_events *h,
                                                      void *data, uint32_t self, uint32_t opcode,
                                                      const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_KEYBOARD_EV_KEYMAP:
        if (!h->keymap)
            return ERR_NOT_SUPPORTED;
        return h->keymap(data, self, a[0].u, a[1].h, a[2].u);
    case JWL_WL_KEYBOARD_EV_ENTER:
        if (!h->enter)
            return ERR_NOT_SUPPORTED;
        return h->enter(data, self, a[0].u, a[1].o, a[2].a.data, a[2].a.size);
    case JWL_WL_KEYBOARD_EV_LEAVE:
        if (!h->leave)
            return ERR_NOT_SUPPORTED;
        return h->leave(data, self, a[0].u, a[1].o);
    case JWL_WL_KEYBOARD_EV_KEY:
        if (!h->key)
            return ERR_NOT_SUPPORTED;
        return h->key(data, self, a[0].u, a[1].u, a[2].u, a[3].u);
    case JWL_WL_KEYBOARD_EV_MODIFIERS:
        if (!h->modifiers)
            return ERR_NOT_SUPPORTED;
        return h->modifiers(data, self, a[0].u, a[1].u, a[2].u, a[3].u, a[4].u);
    case JWL_WL_KEYBOARD_EV_REPEAT_INFO:
        if (!h->repeat_info)
            return ERR_NOT_SUPPORTED;
        return h->repeat_info(data, self, a[0].i, a[1].i);
    }
    return ERR_INVALID_ARGS;
}


