/* wl_subsurface.place_above, request 2: restack the sub-surface */
static inline status_t jwl_wl_subsurface_place_above(struct jwl_conn *c, uint32_t self,
                                                     uint32_t sibling)
{
    const union jwl_arg jwl_a[] = {
        { .o = sibling },
    };
    return jwl_send(c, self, JWL_WL_SUBSURFACE_REQ_PLACE_ABOVE,
                    &jwl_wl_subsurface_interface.requests[JWL_WL_SUBSURFACE_REQ_PLACE_ABOVE],
                    jwl_a);
}

/* wl_subsurface.place_below, request 3: restack the sub-surface */
static inline status_t jwl_wl_subsurface_place_below(struct jwl_conn *c, uint32_t self,
                                                     uint32_t sibling)
{
    const union jwl_arg jwl_a[] = {
        { .o = sibling },
    };
    return jwl_send(c, self, JWL_WL_SUBSURFACE_REQ_PLACE_BELOW,
                    &jwl_wl_subsurface_interface.requests[JWL_WL_SUBSURFACE_REQ_PLACE_BELOW],
                    jwl_a);
}

/* wl_subsurface.set_sync, request 4: set sub-surface to synchronized mode */
static inline status_t jwl_wl_subsurface_set_sync(struct jwl_conn *c, uint32_t self)
{
    return jwl_send(c, self, JWL_WL_SUBSURFACE_REQ_SET_SYNC,
                    &jwl_wl_subsurface_interface.requests[JWL_WL_SUBSURFACE_REQ_SET_SYNC], NULL);
}

/* wl_subsurface.set_desync, request 5: set sub-surface to desynchronized mode */
static inline status_t jwl_wl_subsurface_set_desync(struct jwl_conn *c, uint32_t self)
{
    return jwl_send(c, self, JWL_WL_SUBSURFACE_REQ_SET_DESYNC,
                    &jwl_wl_subsurface_interface.requests[JWL_WL_SUBSURFACE_REQ_SET_DESYNC], NULL);
}

/* Calls h's handler for wl_subsurface request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_subsurface
 * doesn't have. */
static inline status_t jwl_wl_subsurface_dispatch_request(
        const struct jwl_wl_subsurface_requests *h, void *data, uint32_t self, uint32_t opcode,
        const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_SUBSURFACE_REQ_DESTROY:
        if (!h->destroy)
            return ERR_NOT_SUPPORTED;
        return h->destroy(data, self);
    case JWL_WL_SUBSURFACE_REQ_SET_POSITION:
        if (!h->set_position)
            return ERR_NOT_SUPPORTED;
        return h->set_position(data, self, a[0].i, a[1].i);
    case JWL_WL_SUBSURFACE_REQ_PLACE_ABOVE:
        if (!h->place_above)
            return ERR_NOT_SUPPORTED;
        return h->place_above(data, self, a[0].o);
    case JWL_WL_SUBSURFACE_REQ_PLACE_BELOW:
        if (!h->place_below)
            return ERR_NOT_SUPPORTED;
        return h->place_below(data, self, a[0].o);
    case JWL_WL_SUBSURFACE_REQ_SET_SYNC:
        if (!h->set_sync)
            return ERR_NOT_SUPPORTED;
        return h->set_sync(data, self);
    case JWL_WL_SUBSURFACE_REQ_SET_DESYNC:
        if (!h->set_desync)
            return ERR_NOT_SUPPORTED;
        return h->set_desync(data, self);
    }
    return ERR_INVALID_ARGS;
}


/* ---- wl_fixes, upstream version 2: wayland protocol fixes ---- */

#define JWL_WL_FIXES_VERSION 2u

/* wl_fixes requests: the opcode, and the version each came in. */
#define JWL_WL_FIXES_REQ_DESTROY                 0u
#define JWL_WL_FIXES_REQ_DESTROY_SINCE           1u
#define JWL_WL_FIXES_REQ_DESTROY_REGISTRY        1u
#define JWL_WL_FIXES_REQ_DESTROY_REGISTRY_SINCE  1u
#define JWL_WL_FIXES_REQ_ACK_GLOBAL_REMOVE       2u
#define JWL_WL_FIXES_REQ_ACK_GLOBAL_REMOVE_SINCE 2u
#define JWL_WL_FIXES_REQ_DESTRUCTORS             0x00000001u

/* wl_fixes.error: wl_fixes error values */
enum jwl_wl_fixes_error {
    JWL_WL_FIXES_ERROR_INVALID_ACK_REMOVE = 0, /* unknown global or the global is not removed */
};

/* What the compositor does with each wl_fixes request: one handler per
 * message, or NULL (its dispatcher answers ERR_NOT_SUPPORTED). Each gets
 * the object's data (what libjwl's object map holds for it), its id
 * and the arguments the codec decoded and checked. */
struct jwl_wl_fixes_requests {
    status_t (*destroy)(void *data, uint32_t self);
    status_t (*destroy_registry)(void *data, uint32_t self, uint32_t registry);
    status_t (*ack_global_remove)(void *data, uint32_t self, uint32_t registry, uint32_t name);
};

/* wl_fixes.destroy, request 0, destroys the object: destroys this object */
static inline status_t jwl_wl_fixes_destroy(struct jwl_conn *c, uint32_t self)
{
    return jwl_send(c, self, JWL_WL_FIXES_REQ_DESTROY,
                    &jwl_wl_fixes_interface.requests[JWL_WL_FIXES_REQ_DESTROY], NULL);
}

/* wl_fixes.destroy_registry, request 1: destroy a wl_registry */
static inline status_t jwl_wl_fixes_destroy_registry(struct jwl_conn *c, uint32_t self,
                                                     uint32_t registry)
{
    const union jwl_arg jwl_a[] = {
        { .o = registry },
    };
    return jwl_send(c, self, JWL_WL_FIXES_REQ_DESTROY_REGISTRY,
                    &jwl_wl_fixes_interface.requests[JWL_WL_FIXES_REQ_DESTROY_REGISTRY], jwl_a);
}

/* wl_fixes.ack_global_remove, request 2, since 2: acknowledge global removal */
static inline status_t jwl_wl_fixes_ack_global_remove(struct jwl_conn *c, uint32_t self,
                                                      uint32_t registry, uint32_t name)
{
    const union jwl_arg jwl_a[] = {
        { .o = registry },
        { .u = name },
    };
    return jwl_send(c, self, JWL_WL_FIXES_REQ_ACK_GLOBAL_REMOVE,
                    &jwl_wl_fixes_interface.requests[JWL_WL_FIXES_REQ_ACK_GLOBAL_REMOVE], jwl_a);
}

/* Calls h's handler for wl_fixes request `opcode` on object `self`
 * (data: what the object map holds for it) with the arguments a, as
 * the codec decoded them. Returns the handler's status;
 * ERR_NOT_SUPPORTED if h has none for it (handles in a are then
 * still the caller's, to close); ERR_INVALID_ARGS for an opcode wl_fixes
 * doesn't have. */
static inline status_t jwl_wl_fixes_dispatch_request(const struct jwl_wl_fixes_requests *h,
                                                     void *data, uint32_t self, uint32_t opcode,
                                                     const union jwl_arg *a)
{
    switch (opcode) {
    case JWL_WL_FIXES_REQ_DESTROY:
        if (!h->destroy)
            return ERR_NOT_SUPPORTED;
        return h->destroy(data, self);
    case JWL_WL_FIXES_REQ_DESTROY_REGISTRY:
        if (!h->destroy_registry)
            return ERR_NOT_SUPPORTED;
        return h->destroy_registry(data, self, a[0].o);
    case JWL_WL_FIXES_REQ_ACK_GLOBAL_REMOVE:
        if (!h->ack_global_remove)
            return ERR_NOT_SUPPORTED;
        return h->ack_global_remove(data, self, a[0].o, a[1].u);
    }
    return ERR_INVALID_ARGS;
}
